\begin{tikzpicture}[>=stealth,font=\scriptsize]
\path[use as bounding box] (-5.7,-5.7) rectangle (5.7,5.7);
\begin{scope}\clip (-5,-5) rectangle (5,5);
\draw[blue,thick,<->,domain=-3:2,samples=2] plot (\x,{2*\x+1});
\foreach \x in {0,1,2}{\fill[blue] (\x,{2*\x+1}) circle (2pt);}
\end{scope}\end{tikzpicture}

